int hidp_setup_session(struct hidp_session *session, struct hidp_connadd_req *req) {
    int err = -ENOMEM;

    if (!session || !req) {
        return -EINVAL;
    }

    session->hid_dev = hid_allocate_device();
    if (!session->hid_dev) {
        return -ENOMEM;
    }

    session->hid_dev->vendor = req->vendor;
    session->hid_dev->product = req->product;
    session->hid_dev->version = req->version;
    session->hid_dev->country = req->country;

    if (hid_is_blacklisted(session->hid_dev->vendor, session->hid_dev->product)) {
        hid_free_device(session->hid_dev);
        return -EPERM;
    }

    session->read_data = kmalloc(req->read_buffer_size, GFP_KERNEL);
    if (!session->read_data) {
        hid_free_device(session->hid_dev);
        return -ENOMEM;
    }

    session->read_data_size = req->read_buffer_size;

    if (copy_from_user(session->read_data, req->read_buffer, req->read_buffer_size)) {
        kfree(session->read_data);
        hid_free_device(session->hid_dev);
        return -EFAULT;
    }

    err = hid_register_device(session->hid_dev);
    if (err < 0) {
        kfree(session->read_data);
        hid_free_device(session->hid_dev);
        return err;
    }

    return 0;
}
